import{_ as e,H as a,f as i,i as d}from"./chunks/framework.Cvt1eIE0.js";const p=JSON.parse('{"title":"芒伊木 Wiki - 基础布局修复设计方案","description":"","frontmatter":{},"headers":[],"relativePath":"docs/superpowers/specs/2026-05-19-wiki-layout-fix-design.md","filePath":"docs/superpowers/specs/2026-05-19-wiki-layout-fix-design.md"}'),c={name:"docs/superpowers/specs/2026-05-19-wiki-layout-fix-design.md"};function t(r,o,l,s,n,h){return a(),i("div",null,[...o[0]||(o[0]=[d('<h1 id="芒伊木-wiki-基础布局修复设计方案" tabindex="-1">芒伊木 Wiki - 基础布局修复设计方案 <a class="header-anchor" href="#芒伊木-wiki-基础布局修复设计方案" aria-label="Permalink to &quot;芒伊木 Wiki - 基础布局修复设计方案&quot;">​</a></h1><h2 id="_1-目标与背景" tabindex="-1">1. 目标与背景 <a class="header-anchor" href="#_1-目标与背景" aria-label="Permalink to &quot;1. 目标与背景&quot;">​</a></h2><p><strong>目标</strong>：修复当前 VitePress 页面中，正文的横向元素（如 <code>&lt;hr&gt;</code> 分割线、<code>h1</code>/<code>h2</code> 标题的底部边框）会穿透或连接到右侧悬浮卡片（<code>Infobox</code>, <code>MediaCard</code>）的视觉 Bug。 <strong>背景</strong>：基于用户对 <code>WX-78 Wiki</code> 成功案例的考察，我们决定放弃 VitePress 的现代居中博客流排版，转向传统的<strong>浮动避让（Float Logic）</strong> Wiki 风格。即块级元素在遇到右侧浮动的卡片时，应自动缩短宽度，实现视觉上的“零件不相连”。</p><h2 id="_2-架构与实现逻辑" tabindex="-1">2. 架构与实现逻辑 <a class="header-anchor" href="#_2-架构与实现逻辑" aria-label="Permalink to &quot;2. 架构与实现逻辑&quot;">​</a></h2><p>本次修复纯粹在 CSS 层面进行调整，不修改任何 Vue 组件的 DOM 结构。</p><h3 id="_2-1-右侧卡片-浮动源" tabindex="-1">2.1 右侧卡片 (浮动源) <a class="header-anchor" href="#_2-1-右侧卡片-浮动源" aria-label="Permalink to &quot;2.1 右侧卡片 (浮动源)&quot;">​</a></h3><ul><li>组件：<code>.infobox</code>, <code>.media-card</code></li><li>规则： <ul><li>维持 <code>float: right;</code>。</li><li>添加 <code>clear: right;</code> 确保多个卡片在右侧垂直堆叠，不发生水平碰撞。</li><li>设置 <code>margin-left: 24px;</code> 及 <code>margin-bottom: 24px;</code> 确保与左侧被避让的内容之间有明确的呼吸空间（即截图中强调的“大片空白”概念，用于视觉隔离）。</li></ul></li></ul><h3 id="_2-2-正文内容区-避让目标" tabindex="-1">2.2 正文内容区 (避让目标) <a class="header-anchor" href="#_2-2-正文内容区-避让目标" aria-label="Permalink to &quot;2.2 正文内容区 (避让目标)&quot;">​</a></h3><ul><li>元素：<code>.vp-doc h1</code>, <code>.vp-doc h2</code>, <code>.vp-doc h3</code>, <code>.vp-doc hr</code>, <code>.vp-doc p</code>, <code>.vp-doc blockquote</code></li><li>规则： <ul><li><strong>移除强制清理</strong>：确保 <code>.vp-doc hr</code> 等元素<strong>没有</strong>使用 <code>clear: both</code>，否则它们会强制跳到浮动卡片的下方，破坏版面。</li><li><strong>触发 BFC (Block Formatting Context)</strong>：对于带有底部边框的标题（<code>h2</code>等），通过设置 <code>overflow: hidden;</code> 或调整 <code>display</code> 属性触发 BFC，使其宽度被右侧的浮动元素强制限制，从而实现边框自动截断，不穿透卡片。</li></ul></li></ul><h3 id="_2-3-布局宽度-保留选项a基调" tabindex="-1">2.3 布局宽度 (保留选项A基调) <a class="header-anchor" href="#_2-3-布局宽度-保留选项a基调" aria-label="Permalink to &quot;2.3 布局宽度 (保留选项A基调)&quot;">​</a></h3><ul><li>继续维持前一阶段设定的较宽内容区（<code>1100px</code>），确保文字整体偏左，右侧为卡片保留足够的浮动通道。</li></ul><h2 id="_3-测试与验证标准" tabindex="-1">3. 测试与验证标准 <a class="header-anchor" href="#_3-测试与验证标准" aria-label="Permalink to &quot;3. 测试与验证标准&quot;">​</a></h2><ol><li><strong>分割线截断测试</strong>：在插入了 <code>&lt;MediaCard&gt;</code> 的段落上下插入 <code>---</code>（<code>&lt;hr&gt;</code>）。分割线应该只在文字区域内显示，其右侧终点应停在距离卡片左侧外边距（24px）的位置，绝不触碰卡片边框。</li><li><strong>标题边框测试</strong>：在浮动卡片旁边放置带有底部边框的 <code>## 标题</code>。底部边框同样应该被卡片截断。</li><li><strong>多卡片测试</strong>：连续放置两个浮动卡片，它们应在右侧垂直排列，不重叠。</li></ol><h2 id="_4-后续规划-非本次范围" tabindex="-1">4. 后续规划 (非本次范围) <a class="header-anchor" href="#_4-后续规划-非本次范围" aria-label="Permalink to &quot;4. 后续规划 (非本次范围)&quot;">​</a></h2><ul><li>重组单一页面的 Markdown 内容结构，利用更复杂的表格和嵌套组件大幅提升信息密度，达到专业 Wiki 的水平。</li></ul>',15)])])}const _=e(c,[["render",t]]);export{p as __pageData,_ as default};
